export default async function install(app) {
  const left = app.getMount('csmp-breakdowns');
  const right = app.getMount('csmp-summary');
  const bottom = app.getMount('csmp-trend');
  const pdmp = app.layers[app.config.pdmpLayerId];
  const trendLayer = app.layers[app.config.trendLayerId];
  const selectedCounties = new Set();
  const hiddenDrugs = new Set();
  let refreshTimer = null;
  let requestId = 0;
  const moneyFields = [['P_Insurance','Insurance'],['P_Medicaid','Medicaid'],['P_Medicare','Medicare'],['P_Other_Cash_Insurance','Other cash & insurance'],['P_Private_Pay','Private pay'],['P_Workers','Workers comp'],['P_Military','Military'],['P_Indian_Nations','Indian Nations']];
  const classFields = [['C_Opioids','Opioids'],['C_Benzodiazepines','Benzodiazepines'],['C_Stimulants','Stimulants']];
  const scheduleFields = [['Sch_CII','Schedule II'],['Sch_CIII','Schedule III'],['Sch_CIV','Schedule IV'],['Sch_CV','Schedule V']];
  const mmeFields = [['MME_0_19','0–19 MME'],['MME_20_49','20–49 MME'],['MME_50_89','50–89 MME'],['MME_ge90','90+ MME']];
  const supplyFields = [['D_0_3','0–3 days'],['D_4_7','4–7 days'],['D_8_14','8–14 days'],['D_15_21','15–21 days'],['D_22_30','22–30 days'],['DS_g30','30+ days']];
  const allPdmpFields = [...new Set(['county','Naloxone','Male','Female','Unknown_Gender', ...moneyFields, ...classFields, ...scheduleFields, ...mmeFields, ...supplyFields].map(v => Array.isArray(v) ? v[0] : v))];
  const colors = ['var(--app-series-1)','var(--app-series-2)','var(--app-series-3)','var(--app-series-4)','var(--app-series-5)','var(--app-series-6)','var(--app-series-7)','var(--app-series-8)'];
  function el(tag, text, className) { const x=document.createElement(tag); if(text!==undefined) x.textContent=text; if(className) x.className=className; return x; }
  function rootStyle(mount) { mount.replaceChildren(); const root=el('div',undefined,'csmp-root'); root.style.cssText='display:flex;flex-direction:column;gap:10px;min-width:0;color:var(--app-text);font:13px/1.25 system-ui,sans-serif;'; mount.append(root); return root; }
  function card(title) { const c=el('section'); c.style.cssText='border:1px solid var(--app-border-subtle);background:var(--app-surface);border-radius:var(--app-radius);padding:9px;min-width:0;'; const h=el('div',title); h.style.cssText='font-weight:650;margin:0 0 7px;color:var(--app-text);'; c.append(h); return c; }
  function totals(rows, fields) { return fields.map(([field,label]) => ({label,value:rows.reduce((s,r)=>s+(Number(r.attributes[field])||0),0)})); }
  function barChart(title, data) { const c=card(title); const max=Math.max(1,...data.map(d=>d.value)); data.forEach((d,i)=>{ const row=el('div'); row.style.cssText='display:grid;grid-template-columns:minmax(95px,1fr) 4fr auto;gap:7px;align-items:center;margin:5px 0;'; const lab=el('div',d.label); lab.style.cssText='font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--app-text-muted);'; const track=el('div'); track.style.cssText='height:11px;background:var(--app-border-subtle);border-radius:8px;overflow:hidden;'; const fill=el('div'); fill.style.cssText=`height:100%;width:${(d.value/max)*100}%;background:${colors[i%colors.length]};transition:width .2s;`; track.append(fill); const val=el('div',fmt(d.value)); val.style.cssText='font-variant-numeric:tabular-nums;font-size:11px;text-align:right;'; row.append(lab,track,val); c.append(row); }); return c; }
  function fmt(v) { return new Intl.NumberFormat('en-US',{maximumFractionDigits:0,notation:Math.abs(v)>=1000000?'compact':'standard'}).format(v||0); }
  function query(layer, fields, geometry, counties) { const q={where:'1=1',outFields:fields,returnGeometry:false}; if(geometry){q.geometry=geometry;q.spatialRelationship='intersects';} if(counties.size){ const safe=[...counties].map(v=>`'${String(v).replace(/'/g,"''")}'`).join(','); q.where=`county IN (${safe})`; } return layer.queryFeatures(q).then(r=>r.features); }
  function donut(rows) { const c=card('Gender split (%)'); const values=totals(rows,[['Male','Male'],['Female','Female'],['Unknown_Gender','Unknown']]); const sum=values.reduce((a,b)=>a+b.value,0)||1; const box=el('div'); box.style.cssText='display:flex;align-items:center;gap:12px;'; const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'); svg.setAttribute('viewBox','0 0 42 42'); svg.setAttribute('width','96'); svg.setAttribute('height','96'); svg.setAttribute('aria-label','Gender split'); let offset=25; values.forEach((d,i)=>{const p=d.value/sum*100;const circle=document.createElementNS('http://www.w3.org/2000/svg','circle');circle.setAttribute('cx','21');circle.setAttribute('cy','21');circle.setAttribute('r','15.9');circle.setAttribute('fill','none');circle.setAttribute('stroke',colors[i]);circle.setAttribute('stroke-width','7');circle.setAttribute('stroke-dasharray',`${p} ${100-p}`);circle.setAttribute('stroke-dashoffset',String(-offset));circle.setAttribute('transform','rotate(-90 21 21)');offset+=p;svg.append(circle);}); const legend=el('div'); values.forEach((d,i)=>{const r=el('div',`${d.label}: ${(d.value/sum*100).toFixed(1)}%`);r.style.cssText=`margin:5px 0;color:${colors[i]};font-weight:600;`;legend.append(r);}); box.append(svg,legend);c.append(box);return c; }
  function indicator(rows) { const c=card('Total naloxone doses'); const v=rows.reduce((s,r)=>s+(Number(r.attributes.Naloxone)||0),0); const n=el('div',fmt(v));n.style.cssText='font-size:30px;font-weight:700;color:var(--app-accent);font-variant-numeric:tabular-nums;';const t=el('div','Sum of Naloxone across the current county and map filters');t.style.cssText='color:var(--app-text-muted);font-size:11px;margin-top:3px;';c.append(n,t);return c; }
  function countyList(counties) { const c=card('County list'); const note=el('div',selectedCounties.size?`${selectedCounties.size} county${selectedCounties.size===1?'':'ies'} selected — click again to clear.`:'Select one or more counties to filter the measures.'); note.style.cssText='font-size:11px;color:var(--app-text-muted);margin-bottom:6px;'; const box=el('div'); box.style.cssText='display:flex;flex-wrap:wrap;gap:4px;max-height:210px;overflow:auto;padding-right:3px;'; counties.forEach(name=>{const b=el('button',name);b.type='button'; const active=selectedCounties.has(name); b.style.cssText=`border:1px solid var(--app-border);border-radius:12px;padding:3px 7px;cursor:pointer;font-size:11px;background:${active?'var(--app-accent)':'var(--app-surface-raised)'};color:${active?'white':'var(--app-text)'};`;b.addEventListener('click',()=>{active?selectedCounties.delete(name):selectedCounties.add(name); schedule();});box.append(b);});c.append(note,box);return c; }
  function trendChart(rows) { const c=card('Doses by drug type'); const available=[...new Set(rows.map(r=>r.attributes.drugtype).filter(Boolean))].sort(); const yearVals=[...new Set(rows.map(r=>Number(r.attributes.fillyear)).filter(Number.isFinite))].sort((a,b)=>a-b); const active=available.filter(d=>!hiddenDrugs.has(d)); const sums={}; active.forEach(d=>sums[d]=yearVals.map(y=>rows.filter(r=>r.attributes.drugtype===d&&Number(r.attributes.fillyear)===y).reduce((s,r)=>s+(Number(r.attributes.TotalDoses)||0),0))); const max=Math.max(1,...Object.values(sums).flat()); const wrap=el('div'); wrap.style.cssText='width:100%;overflow-x:auto;'; const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'); const w=580,h=185,p={l:38,r:12,t:10,b:29}; svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.style.cssText='display:block;width:100%;min-width:420px;height:auto;'; for(let i=0;i<4;i++){const y=p.t+i*(h-p.t-p.b)/3;const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',p.l);line.setAttribute('x2',w-p.r);line.setAttribute('y1',y);line.setAttribute('y2',y);line.setAttribute('stroke','var(--app-border-subtle)');svg.append(line);} yearVals.forEach((year,i)=>{const x=p.l+(yearVals.length===1?0:i*(w-p.l-p.r)/(yearVals.length-1));const tx=document.createElementNS('http://www.w3.org/2000/svg','text');tx.setAttribute('x',x);tx.setAttribute('y',h-8);tx.setAttribute('text-anchor','middle');tx.setAttribute('font-size','10');tx.setAttribute('fill','var(--app-text-muted)');tx.textContent=year;svg.append(tx);}); active.forEach((drug,di)=>{const vals=sums[drug]; const pts=vals.map((v,i)=>{const x=p.l+(yearVals.length===1?0:i*(w-p.l-p.r)/(yearVals.length-1));const y=h-p.b-(v/max)*(h-p.t-p.b);return [x,y];}); const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',pts.map((q,i)=>`${i?'L':'M'}${q[0]},${q[1]}`).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke',colors[di%colors.length]);path.setAttribute('stroke-width','2.5');svg.append(path);});wrap.append(svg); const legend=el('div');legend.style.cssText='display:flex;flex-wrap:wrap;gap:5px;margin-top:6px;';available.forEach((drug,i)=>{const b=el('button',drug);b.type='button';const on=!hiddenDrugs.has(drug);b.style.cssText=`border:1px solid ${colors[i%colors.length]};border-radius:10px;background:${on?colors[i%colors.length]:'transparent'};color:${on?'white':'var(--app-text)'};padding:2px 7px;font-size:10px;cursor:pointer;`;b.addEventListener('click',()=>{on?hiddenDrugs.add(drug):hiddenDrugs.delete(drug);renderTrendOnly();});legend.append(b);}); c.append(wrap,legend);return c; }
  async function renderTrendOnly(){ const id=++requestId; const geom=app.view.extent; const rows=await query(trendLayer,['county','fillyear','drugtype','TotalDoses'],geom,selectedCounties); if(id!==requestId)return; bottom.replaceChildren(); const root=rootStyle(bottom); root.append(trendChart(rows)); }
  async function refresh(){ const id=++requestId; const geom=app.view.extent; left.replaceChildren(el('div','Updating measures…'));right.replaceChildren(el('div','Updating measures…')); const [rows,trendRows,countyRows]=await Promise.all([query(pdmp,allPdmpFields,geom,selectedCounties),query(trendLayer,['county','fillyear','drugtype','TotalDoses'],geom,selectedCounties),query(pdmp,['county'],null,new Set())]); if(id!==requestId)return; const counties=[...new Set(countyRows.map(r=>r.attributes.county).filter(Boolean))].sort(); const lroot=rootStyle(left); lroot.append(barChart('Prescriptions by payment type',totals(rows,moneyFields)),barChart('Doses by drug class',totals(rows,classFields)),barChart('Doses by schedule',totals(rows,scheduleFields)),barChart('Prescriptions by MME range',totals(rows,mmeFields)),barChart('Prescriptions by day supply range',totals(rows,supplyFields))); const rroot=rootStyle(right);rroot.append(indicator(rows),donut(rows),countyList(counties)); bottom.replaceChildren();const broot=rootStyle(bottom);broot.append(trendChart(trendRows)); }
  function schedule(){ clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{refresh().catch(err=>{left.replaceChildren(el('div',`Unable to refresh dashboard: ${err.message}`));right.replaceChildren();bottom.replaceChildren();});},220); }
  const handle=app.view.watch('extent',schedule);
  app.onCleanup(()=>{handle.remove();clearTimeout(refreshTimer);left.replaceChildren();right.replaceChildren();bottom.replaceChildren();});
  await refresh();
}